"""Lease captured factual IDs to the unchanged ordered DT consumers.

NativePrefixArtifacts, FLA and HF Cache own computation and transitions.
VERL owns padding. This adapter only groups the exact source artifacts already
present in the current response RPC; nothing is retained across policy updates.
"""
import math
import time

import torch


def prepare_native_prefix_leases(runner, requests, *, minibatch_size, eos_token_id, boundary_row_storage=False, observe_boundary_rows=None, individual_prefixes=False):
    from qwen35_native_prefix_artifacts import NativePrefixArtifacts, NativePrefixLease
    from verl import DataProto
    from verl.protocol import pad_dataproto_to_divisor

    started = time.perf_counter()
    batches = [requests[i:i+minibatch_size] for i in range(0, len(requests), minibatch_size)]
    # Reuse the owner's original MIN collective on a boundary known to precede
    # every current action. No current action, query or target is captured.
    prefix_lengths = [runner.model.synchronize_prefix_start(
        min(request['start'] for request in batch)//64*64) for batch in batches]
    row_prefix_lengths = None
    if individual_prefixes:
        # Preserve the original all-rank zero/nonzero branch and its call count.
        # A zero common boundary retains the original no-cache consumer.
        row_prefix_lengths = [tuple(r['start']//64*64 for r in batch) if length else None
                              for batch, length in zip(batches, prefix_lengths)]
        carrier_prefix_lengths = [max(lengths) if lengths is not None else 0 for lengths in row_prefix_lengths]
    needed = {}
    if individual_prefixes:
        for batch, lengths in zip(batches, row_prefix_lengths):
            if lengths is not None:
                for request, length in zip(batch, lengths):
                    needed.setdefault(request['traj_uid'], set()).add(length)
    else:
        for batch, length in zip(batches, prefix_lengths):
            if length:
                for request in batch:
                    needed.setdefault(request['traj_uid'], set()).add(length)

    canonical = {}
    for request in requests:
        uid = request['traj_uid']
        if uid in needed and (uid not in canonical or
                             request['prompt'].numel() > canonical[uid].numel()):
            canonical[uid] = request['prompt']
    if individual_prefixes:
        for batch, lengths in zip(batches, row_prefix_lengths):
            if lengths is not None:
                for request, length in zip(batch, lengths):
                    if not torch.equal(request['prompt'][:length], canonical[request['traj_uid']][:length]):
                        raise ValueError('Original histories do not share the requested factual row prefix')
    else:
        for batch, length in zip(batches, prefix_lengths):
            if length:
                for request in batch:
                    if not torch.equal(request['prompt'][:length], canonical[request['traj_uid']][:length]):
                        raise ValueError('Original histories do not share the requested factual prefix')

    records = list(canonical.items())
    capture_rows = len(records)
    # A native prefix forward gathers FSDP parameters, so all sharding ranks
    # execute the same count of original B4 forwards. Public mesh/collective
    # APIs supply metadata only; the owner retains all parameter transitions.
    weight = runner.model.lm_head.weight
    mesh = getattr(weight, 'device_mesh', None)
    device = runner.model.execution_device
    if mesh is not None and mesh.size() > 1:
        if mesh.ndim > 1:
            mesh = mesh['fsdp']
        count = torch.tensor(capture_rows, device=device, dtype=torch.long)
        torch.distributed.all_reduce(count, op=torch.distributed.ReduceOp.MAX, group=mesh.get_group())
        capture_rows = int(count.item())
    capture_rounds = math.ceil(capture_rows/minibatch_size)
    sources = {}
    capture_tokens = 0
    if capture_rounds:
        indices = DataProto.from_dict(tensors={'canonical_index': torch.arange(len(records))})
        # Capture is a representation producer, not a DT consumer. Keep the
        # original consumer order, but group factual histories by the largest
        # boundary actually needed so native B4 padding is not set by a random
        # long history. VERL owns the permutation and subsequent row padding.
        indices.reorder(torch.tensor(sorted(range(len(records)),
            key=lambda row: max(needed[records[row][0]])), dtype=torch.long))
        indices, _ = pad_dataproto_to_divisor(indices, capture_rounds*minibatch_size)
        indices = indices.batch['canonical_index'].tolist()
        if boundary_row_storage:
            # Match the original sources[uid] last-write semantics after native
            # padding. Earlier repeated slots are not consumed by any lease.
            last_slots = {records[row][0]: slot for slot, row in enumerate(indices)}
        for offset in range(0, len(indices), minibatch_size):
            rows = indices[offset:offset+minibatch_size]
            lengths = sorted(set(n for row in rows for n in needed[records[row][0]]))
            width = max(lengths)
            ids = torch.full((minibatch_size, width), eos_token_id, device=device, dtype=torch.long)
            for i, row in enumerate(rows):
                prompt = records[row][1]
                end = min(width, prompt.numel())
                ids[i, :end] = prompt[:end].to(device)
            if boundary_row_storage:
                boundary_rows = {n: [i for i, row in enumerate(rows)
                    if last_slots[records[row][0]] == offset+i and n in needed[records[row][0]]]
                    for n in lengths}
                artifacts = NativePrefixArtifacts.capture(runner.model, ids, lengths,
                    config=runner.model._conditional.config, boundary_rows=boundary_rows,
                    observe_boundary_rows=observe_boundary_rows)
            else:
                artifacts = NativePrefixArtifacts.capture(runner.model, ids, lengths,
                                                           config=runner.model._conditional.config)
            for i, row in enumerate(rows):
                sources[records[row][0]] = (artifacts, i)
            capture_tokens += ids.numel()
            del ids
    if individual_prefixes:
        leases = [NativePrefixLease([sources[r['traj_uid']] for r in batch], length, prefix_lengths=lengths,
                                    context_lengths=tuple(r['context_tokens'] for r in batch))
                  if lengths is not None else None
                  for batch, length, lengths in zip(batches, carrier_prefix_lengths, row_prefix_lengths)]
    else:
        leases = [NativePrefixLease([sources[r['traj_uid']] for r in batch], length)
                  if length else None for batch, length in zip(batches, prefix_lengths)]
    torch.cuda.synchronize()
    return leases, dict(capture_rounds=capture_rounds, local_unique_histories=len(records),
        consumer_batches=len(batches), capture_token_slots=capture_tokens,
        original_shared_prefix_token_slots=sum(len(b)*n for b,n in zip(batches,prefix_lengths)),
        capture_and_preparation_seconds=time.perf_counter()-started)

"""Exact native Qwen3.5 artifacts for explicitly supplied prefix leases.

The HF model, FLA state operator and Transformers Cache retain ownership of
all computation and state transitions. This file does not implement attention,
recurrence, convolution, cache updates, attribution or a training scheduler.
It is not enabled by the default DT runner or a production launcher.
"""
from dataclasses import dataclass

import torch


@dataclass
class NativePrefixArtifacts:
    config: object
    input_ids: torch.Tensor
    layers: list
    boundary_rows: object = None

    @classmethod
    @torch.no_grad()
    def capture(cls, model, input_ids, prefix_lengths, *, config, observe_native_cache=None, boundary_rows=None, observe_boundary_rows=None):
        """Read requested boundaries during one unchanged native forward.

        Only the supplied factual IDs are forwarded. A boundary consumes
        tensors up to that boundary. FLA emits its own FP32 final state; HF
        Cache determines the stored dtype when the artifacts are consumed.
        The caller owns the lifetime and grouping of these exact artifacts.
        """
        from accelerated.native_capture_events import LocalCaptureEvents
        from fla.ops.gated_delta_rule.chunk import chunk_gated_delta_rule_fwd
        from fla.ops.common.chunk_delta_h import chunk_gated_delta_rule_fwd_h
        from transformers.cache_utils import DynamicCache, LinearAttentionCacheLayerMixin

        lengths = sorted(set(int(n) for n in prefix_lengths))
        if not lengths or any(n < 64 or n % 64 or n > input_ids.shape[1] for n in lengths):
            raise ValueError('Native DT prefix boundaries must be positive 64-token boundaries in the factual input')
        selected_rows = None
        if boundary_rows is not None:
            selected_rows = {n: tuple(int(row) for row in boundary_rows.get(n, ())) for n in lengths}
            if any(len(set(rows)) != len(rows) or any(row < 0 or row >= input_ids.shape[0] for row in rows)
                   for rows in selected_rows.values()):
                raise ValueError('Selected native boundary rows must be distinct original capture rows')
        cache = DynamicCache(config=config)
        layers = model.model.language_model.layers
        artifacts = [None] * len(layers)
        active = [None]
        pending = {}
        windows = {}
        handles = []

        def state_event(frame, kind, value):
            if kind != 'return' or value is None:
                return
            i = active[0]
            f = frame.f_locals
            if i is None or f['initial_state'] is not None or f['cu_seqlens'] is not None:
                raise ValueError('Prefix artifact capture requires the original dense prefill from an empty cache')
            pending[i] = {name: f[name].detach() for name in ('k', 'w', 'u', 'g')}
            pending[i]['final_state'] = f['final_state'].detach()

        def begin(_module, _args, i):
            active[0] = i

        def projection(_module, _args, output, i, width):
            # Exact native pre-convolution projection. HF's prefill stores
            # the last conv_kernel_size columns; no convolution is repeated.
            if selected_rows is None:
                windows[i] = {n: output[:, n-width:n].transpose(1, 2).detach().cpu()
                              for n in lengths}
            else:
                windows[i] = {n: output[:, n-width:n].index_select(0,
                    torch.tensor(rows, device=output.device, dtype=torch.long)).transpose(1, 2).detach().cpu()
                    for n, rows in selected_rows.items() if rows}
                if observe_boundary_rows is not None:
                    for n, rows in selected_rows.items():
                        if rows:
                            observe_boundary_rows('conv', i, n, rows,
                                output[:, n-width:n].transpose(1, 2).detach(), windows[i][n])

        def end(_module, _args, _output, i):
            owner_layer = cache.layers[i]
            if isinstance(owner_layer, LinearAttentionCacheLayerMixin):
                captured = pending.pop(i)
                boundaries = {}
                previous_length = 0
                previous_state = None
                for n in lengths:
                    if n == input_ids.shape[1]:
                        state = captured['final_state']
                    else:
                        h, v_new, state = chunk_gated_delta_rule_fwd_h(
                            k=captured['k'][:, previous_length:n].contiguous(),
                            w=captured['w'][:, previous_length:n].contiguous(),
                            u=captured['u'][:, previous_length:n].contiguous(),
                            g=captured['g'][:, previous_length:n].contiguous(),
                            initial_state=previous_state, output_final_state=True,
                            save_new_value=False)
                        del h, v_new
                    if selected_rows is None:
                        boundaries[n] = (windows[i].pop(n), state.detach().cpu())
                    elif selected_rows[n]:
                        indices = torch.tensor(selected_rows[n], device=state.device, dtype=torch.long)
                        boundaries[n] = (windows[i].pop(n), state.index_select(0, indices).detach().cpu())
                        if observe_boundary_rows is not None:
                            observe_boundary_rows('state', i, n, selected_rows[n],
                                state.detach(), boundaries[n][1])
                    # The public owner accepts its FP32 final state as the
                    # next segment's initial state. Consume each token once;
                    # no restart from token zero for every requested boundary.
                    previous_length, previous_state = n, state
                    del state
                del previous_state, captured
                windows.pop(i)
                artifacts[i] = {'boundaries': boundaries}
            else:
                artifacts[i] = {'keys': owner_layer.keys.detach().cpu(),
                                'values': owner_layer.values.detach().cpu()}

        try:
            for i, layer in enumerate(layers):
                handles.append(layer.register_forward_pre_hook(
                    lambda m, a, i=i: begin(m, a, i)))
                if isinstance(cache.layers[i], LinearAttentionCacheLayerMixin):
                    mixer = layer.linear_attn
                    handles.append(mixer.in_proj_qkv.register_forward_hook(
                        lambda m, a, o, i=i, width=mixer.conv_kernel_size:
                            projection(m, a, o, i, width)))
                handles.append(layer.register_forward_hook(
                    lambda m, a, o, i=i: end(m, a, o, i)))
            with LocalCaptureEvents([chunk_gated_delta_rule_fwd.__code__], state_event,
                                    returns_only=True):
                forward = getattr(model, 'forward_root', model)
                output = forward(input_ids=input_ids, past_key_values=cache,
                                 use_cache=True, logits_to_keep=1)
            if observe_native_cache is not None:
                observe_native_cache(cache)
            del output
        finally:
            for handle in handles:
                handle.remove()
            pending.clear()
            windows.clear()
        if selected_rows is not None:
            return cls(config, input_ids.detach().cpu(), artifacts,
                boundary_rows={n: {row: index for index, row in enumerate(rows)}
                               for n, rows in selected_rows.items()})
        return cls(config, input_ids.detach().cpu(), artifacts)

    def materialize(self, prefix_length, *, device, rows=None):
        rows = range(self.input_ids.shape[0]) if rows is None else rows
        return compose_native_prefix_cache(
            self.config, [(self, int(row)) for row in rows], prefix_length, device=device)


@torch.no_grad()
def compose_native_prefix_cache(config, sources, prefix_length, *, device, prefix_lengths=None):
    """Batch exact artifacts with the original Cache's public update methods.

    In particular, conv state is written before recurrent state, matching
    the HF forward and retaining the owner's dtype conversion and lifecycle.
    No Cache fields or transition flags are assigned by this adapter.
    """
    if prefix_lengths is not None:
        return _compose_row_prefix_cache(config, sources, prefix_length, prefix_lengths, device=device)
    from transformers.cache_utils import DynamicCache, LinearAttentionCacheLayerMixin

    result = DynamicCache(config=config)
    for i, layer in enumerate(result.layers):
        if isinstance(layer, LinearAttentionCacheLayerMixin):
            states = [source.layers[i]['boundaries'][prefix_length] for source, row in sources]
            if all(getattr(source, 'boundary_rows', None) is None for source, row in sources):
                conv = torch.cat([state[0][row:row+1] for state, (_, row) in zip(states, sources)])
                recurrent = torch.cat([state[1][row:row+1] for state, (_, row) in zip(states, sources)])
            else:
                rows = [row if getattr(source, 'boundary_rows', None) is None
                        else source.boundary_rows[prefix_length][row] for source, row in sources]
                conv = torch.cat([state[0][row:row+1] for state, row in zip(states, rows)])
                recurrent = torch.cat([state[1][row:row+1] for state, row in zip(states, rows)])
            result.update_conv_state(conv.to(device), i)
            result.update_recurrent_state(recurrent.to(device), i)
        else:
            keys = torch.cat([source.layers[i]['keys'][row:row+1, :, :prefix_length]
                              for source, row in sources])
            values = torch.cat([source.layers[i]['values'][row:row+1, :, :prefix_length]
                                for source, row in sources])
            result.update(keys.to(device), values.to(device), i)
    return result


@torch.no_grad()
def _compose_row_prefix_cache(config, sources, prefix_length, prefix_lengths, *, device):
    """Represent literal row prefixes in the original Cache's public carrier.

    FA rows are padded after their real prefix to a shared physical width.
    The runner owns the mask and original positions for those padded columns.
    GDN rows select their real captured boundary; no padding enters recurrence.
    """
    from transformers.cache_utils import DynamicCache, LinearAttentionCacheLayerMixin

    lengths = tuple(int(n) for n in prefix_lengths)
    if (len(lengths) != len(sources) or not lengths or max(lengths) != prefix_length
            or any(n < 64 or n % 64 for n in lengths)):
        raise ValueError('Row prefix lengths must match exact positive captured boundaries')
    result = DynamicCache(config=config)
    for i, layer in enumerate(result.layers):
        if isinstance(layer, LinearAttentionCacheLayerMixin):
            states = [source.layers[i]['boundaries'][n] for (source, row), n in zip(sources, lengths)]
            if all(getattr(source, 'boundary_rows', None) is None for source, row in sources):
                conv = torch.cat([state[0][row:row+1] for state, (_, row) in zip(states, sources)])
                recurrent = torch.cat([state[1][row:row+1] for state, (_, row) in zip(states, sources)])
            else:
                rows = [row if getattr(source, 'boundary_rows', None) is None
                        else source.boundary_rows[n][row] for (source, row), n in zip(sources, lengths)]
                conv = torch.cat([state[0][row:row+1] for state, row in zip(states, rows)])
                recurrent = torch.cat([state[1][row:row+1] for state, row in zip(states, rows)])
            result.update_conv_state(conv.to(device), i)
            result.update_recurrent_state(recurrent.to(device), i)
        else:
            keys = torch.cat([torch.nn.functional.pad(
                source.layers[i]['keys'][row:row+1, :, :n], (0, 0, 0, prefix_length-n))
                for (source, row), n in zip(sources, lengths)])
            values = torch.cat([torch.nn.functional.pad(
                source.layers[i]['values'][row:row+1, :, :n], (0, 0, 0, prefix_length-n))
                for (source, row), n in zip(sources, lengths)])
            result.update(keys.to(device), values.to(device), i)
    return result


@dataclass
class NativePrefixLease:
    """Exact artifacts for one original consumer; HF owns the fresh cache."""
    sources: list
    prefix_length: int
    prefix_lengths: tuple | None = None
    context_lengths: tuple | None = None

    def __call__(self, factual_ids):
        if self.prefix_lengths is not None:
            if factual_ids.shape != (len(self.sources), self.prefix_length):
                raise ValueError('Prepared row prefix lease and factual input shapes differ')
            actual = factual_ids.detach().cpu()
            if len(self.prefix_lengths) != len(self.sources):
                raise ValueError('One original prefix length is required per factual row')
            for i, ((source, row), n) in enumerate(zip(self.sources, self.prefix_lengths)):
                if not torch.equal(actual[i, :n], source.input_ids[row, :n]):
                    raise ValueError('Prepared row prefix lease does not match exact factual token IDs')
            return compose_native_prefix_cache(self.sources[0][0].config, self.sources,
                self.prefix_length, device=factual_ids.device, prefix_lengths=self.prefix_lengths)
        if factual_ids.shape != (len(self.sources), self.prefix_length):
            raise ValueError('Prepared prefix lease and factual input shapes differ')
        actual = factual_ids.detach().cpu()
        for i, (source, row) in enumerate(self.sources):
            if not torch.equal(actual[i], source.input_ids[row, :self.prefix_length]):
                raise ValueError('Prepared prefix lease does not match exact factual token IDs')
        return compose_native_prefix_cache(self.sources[0][0].config, self.sources,
                                          self.prefix_length, device=factual_ids.device)
